// Import pdfjsLib from pdfjs-dist and NLP.js for NLP functionalities
import * as pdfjsLib from 'pdfjs-dist';
import { NlpManager } from 'node-nlp';

// Set the workerSrc globally to avoid issues with the PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

// Initialize the NLP Manager
const manager = new NlpManager({ languages: ['en'] });

// Define your extended list of common computer science keywords
const csKeywords = [ 
  'Java', 'Python', 'JavaScript', 'C++', 'C#', 'HTML', 'CSS', 
  'SQL', 'React', 'Node.js', 'Machine Learning', 'AI', 'Data Science', 
  'Algorithms', 'Data Structures', 'Cloud Computing', 'Git', 'Docker', 
  'Kubernetes', 'Agile', 'Scrum', 'Software Development', 'DevOps', 
  'Web Development', 'Mobile Development', 'Cybersecurity', 
  'Database Management', 'API', 'REST', 'GraphQL'
];

const extractCSKeywords = async (text) => {
  const keywords = [];

  // Use NLP.js to extract entities and categorize them
  const response = await manager.process('en', text);

  // Check if the response contains any entities
  if (response.entities) {
    response.entities.forEach((entity) => {
      if (csKeywords.includes(entity.sourceText)) {
        keywords.push(entity.sourceText); // Collect relevant computer science keywords
      }
    });
  }

  // Add additional logic to count keyword frequency
  const frequencyMap = keywords.reduce((acc, keyword) => {
    acc[keyword] = (acc[keyword] || 0) + 1;
    return acc;
  }, {});

  // Convert frequency map to an array of grouped keywords
  const groupedKeywords = Object.keys(frequencyMap).map((key) => ({
    keyword: key,
    frequency: frequencyMap[key],
  }));

  // Sort by frequency in descending order
  groupedKeywords.sort((a, b) => b.frequency - a.frequency);

  return groupedKeywords;
};

const parsePDF = async (file) => {
  const reader = new FileReader();
  reader.readAsArrayBuffer(file);

  return new Promise((resolve, reject) => {
    reader.onload = async function () {
      try {
        const typedArray = new Uint8Array(reader.result);
        const pdf = await pdfjsLib.getDocument(typedArray).promise;

        if (!pdf || !pdf.numPages) {
          reject(new Error('Failed to load PDF document or no pages found.'));
          return;
        }

        let parsedText = '';

        // Loop through all the pages
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();

          // Extract text from each page
          const pageText = textContent.items.map((item) => item.str).join(' ');
          parsedText += pageText + '\n';
        }

        // Extract computer science keywords
        const keywords = await extractCSKeywords(parsedText);
        resolve({ parsedText, keywords }); // Resolve with both parsed text and keywords
      } catch (error) {
        reject(error);
      }
    };

    reader.onerror = function (error) {
      reject(error);
    };
  });
};

export { parsePDF };
